    "B4-PC1": {"host": "192.168.122.37", "ip": "10.2.1.10"},
    "B4-PC2": {"host": "192.168.122.38", "ip": "10.2.1.11"},
    "B4-PC3": {"host": "192.168.122.39", "ip": "10.2.2.10"},  # guest
    "B4-PC4": {"host": "192.168.122.40", "ip": "10.2.2.11"},  # guest
}

NON_GUEST = ["B1-PC1", "B1-PC2", "B2-PC1", "B2-PC2", "B3-PC1", "B3-PC2", "B4-PC1", "B4-PC2"]
GUEST = ["B4-PC3", "B4-PC4"]
ALL_IPS = {name: info["ip"] for name, info in HOSTS.items()}
INTERNET = ["8.8.8.8", "1.1.1.1"]

def ping_from(src_name, dst_ip):
    try:
        conn = ConnectHandler(
            host=HOSTS[src_name]["host"], username="root", password="alpine",
            device_type="linux"
        )
        out = conn.send_command(f"ping -c 2 -W 3 {dst_ip}", read_timeout=15)
        conn.disconnect()
        success = "0% packet loss" in out or ", 0 packets lost" in out or "2 packets received" in out or "1 packets received" in out
        return src_name, dst_ip, success
    except Exception as e:
        return src_name, dst_ip, f"ERROR: {e}"

results = {}
tasks = []

# Non-guest to non-guest
for src in NON_GUEST:
    for dst in NON_GUEST:
        if src != dst:
            tasks.append((src, ALL_IPS[dst]))

# Guest to guest
for src in GUEST:
    for dst in GUEST:
        if src != dst:
            tasks.append((src, ALL_IPS[dst]))

