    for dst in GUEST:
        tasks.append((src, ALL_IPS[dst]))

# Internet from all
for src in NON_GUEST + GUEST:
    for ip in INTERNET:
        tasks.append((src, ip))

with ThreadPoolExecutor(max_workers=10) as pool:
    futures = [pool.submit(ping_from, s, d) for s, d in tasks]
    for f in as_completed(futures):
        src, dst, ok = f.result()
        results[(src, dst)] = ok

# Report
