ng_pass = 0
ng_fail = 0
for src in NON_GUEST:
    for dst in NON_GUEST:
        if src != dst:
            ok = results.get((src, ALL_IPS[dst]))
            if ok is True:
                ng_pass += 1
            else:
                ng_fail += 1
                print(f"  FAIL: {src} -> {dst} ({ALL_IPS[dst]}): {ok}")
print(f"  {ng_pass} pass, {ng_fail} fail")

print("\n=== Guest to guest (should PASS) ===")
for src in GUEST:
    for dst in GUEST:
        if src != dst:
            ok = results.get((src, ALL_IPS[dst]))
            print(f"  {src} -> {dst}: {'PASS' if ok is True else f'FAIL: {ok}'}")

print("\n=== Guest <-> non-guest (should FAIL) ===")
gng_correct = 0
gng_wrong = 0
for src in GUEST:
    for dst in NON_GUEST:
        ok = results.get((src, ALL_IPS[dst]))
        if ok is True:
            gng_wrong += 1
            print(f"  WRONG PASS: {src} -> {dst}")
