        ok = results.get((src, ALL_IPS[dst]))
        if ok is True:
            gng_wrong += 1
            print(f"  WRONG PASS: {src} -> {dst}")
        else:
            gng_correct += 1
print(f"  {gng_correct} correctly blocked, {gng_wrong} wrong passes")

print("\n=== Internet (should PASS) ===")
inet_pass = 0
inet_fail = 0
for src in NON_GUEST + GUEST:
